<script setup lang="ts">
import {ref,reactive,computed,watch,onMounted,onBeforeUnmount} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {Search,SlidersHorizontal,PanelLeftClose,PanelLeftOpen,Truck,Ship,TrainFront,TriangleAlert} from 'lucide-vue-next';
import {get,message} from '../api';
import {label,ton} from '../fulfillment';
import WaybillTrackingMap from '../components/WaybillTrackingMap.vue';
import TrackingElementPopup from '../components/TrackingElementPopup.vue';
import TrackingReplay from '../components/TrackingReplay.vue';
import {validTrack,trackAt} from '../tracking-motion';
import {referencePosition} from '../tracking-reference-motion';
import {unpackTracking} from '../tracking-payload';
const route=useRoute(),router=useRouter(),mapRef=ref<any>(),rows=ref<any[]>([]),total=ref(0),detail=ref<any>(),element=ref<any>(),busy=ref(false),detailBusy=ref(false),error=ref(''),detailError=ref(''),panelOpen=ref(true),filtersOpen=ref(false),includeTest=ref(false),dismissed=ref<string[]>([]);
const query=reactive({waybill:'',shipper:'',cargo:'',origin:'',destination:'',asset:'',mmsi:'',min:undefined as number|undefined,max:undefined as number|undefined,status:'',mode:'ROAD',page:1,pageSize:12});
const applied=ref<any>({});
const replay=ref(false),replayAt=ref<number>(),replayIds=ref<string[]>([]),referenceAt=ref(Date.now());
const canReplay=computed(()=>mapAssets.value.some((a:any)=>validTrack(a).length>1));
const displayElement=computed(()=>replay.value&&replayAt.value!=null&&element.value?.stage?{...element.value,position:trackAt(element.value,replayAt.value)||element.value.position,replayAt:replayAt.value}:element.value?.movement?{...element.value,position:referencePosition(element.value,referenceAt.value)}:element.value);
const themes=computed(()=>route.path.endsWith('/themes')),modeName=computed(()=>label(query.mode));
const assetMatches=(a:any)=>!themes.value||a.mode===query.mode&&(!applied.value.asset||a.title.toLowerCase().includes(applied.value.asset.trim().toLowerCase()))&&(query.mode!=='WATER'||!applied.value.mmsi||a.mmsi.includes(applied.value.mmsi.trim()));
const viewAssets=computed(()=>rows.value.flatMap(w=>w.assets.filter(assetMatches).map((a:any)=>({...a,waybill:w}))));
const mapAssets=computed(()=>(detail.value&&(!themes.value||replay.value)?detail.value.assets:viewAssets.value).filter(assetMatches));
const mapNodes=computed(()=>(detail.value?.nodes||[]).filter((n:any)=>!themes.value||n.mode===query.mode||n.ledgers?.some((l:any)=>l.mode===query.mode))),mapSegments=computed(()=>{const segments=(detail.value&&(!themes.value||replay.value)?detail.value.segments:rows.value.flatMap(w=>w.segments||[])).filter((s:any)=>!themes.value||s.mode===query.mode);return [...new Map(segments.map((s:any)=>[[s.mode,s.origin?.name,s.destination?.name].join('|'),s])).values()] as any[];});
const warning=computed(()=>{const candidates=(detail.value?[detail.value]:rows.value).flatMap(w=>w.assets.filter(assetMatches).flatMap((v:any)=>v.alerts.map((a:any)=>({...a,waybill:w})))).filter(a=>!dismissed.value.includes(a.id||a.taskId+':'+a.type));return candidates.find(a=>a.level==='HIGH')||candidates[0];});
const unlocated=computed(()=>element.value&&!element.value.position);
let poll:any,motionClock:any,sequence=0,selection=0,activeLoads=0;
function params(){return {waybill:query.waybill||undefined,shipper:query.shipper||undefined,cargo:themes.value?undefined:query.cargo||undefined,origin:themes.value?undefined:query.origin||undefined,destination:themes.value?undefined:query.destination||undefined,asset:themes.value?query.asset||undefined:undefined,mmsi:themes.value&&query.mode==='WATER'?query.mmsi||undefined:undefined,minKg:themes.value||query.min==null?undefined:Math.round(query.min*1000),maxKg:themes.value||query.max==null?undefined:Math.round(query.max*1000),status:themes.value?undefined:query.status||undefined,mode:themes.value?query.mode:undefined,page:query.page,pageSize:query.pageSize,includeTest:String(includeTest.value),compact:'true'};}
async function select(id:string,assetId?:string,quiet=false){const seq=++selection;if(!quiet)detailBusy.value=true;detailError.value='';try{const d=unpackTracking(await get('/tracking/waybills/'+id,{includeTest:String(includeTest.value),compact:'true'}));if(seq!==selection)return;const changed=detail.value?.id!==id;detail.value=d;if(assetId)element.value=d.assets.find((a:any)=>a.id===assetId)||null;else if(changed)element.value=null;else if(element.value)element.value=d.assets.find((a:any)=>a.id===element.value.id)||d.nodes.find((n:any)=>n.id===element.value.id)||null;if(!quiet)await router.replace({query:{businessId:id,...(assetId?{assetId}:{})}});}catch(e){if(seq===selection)detailError.value=message(e);}finally{if(seq===selection)detailBusy.value=false;}}
async function load(quiet=false){if(quiet&&activeLoads)return;activeLoads++;const seq=++sequence;if(!quiet){busy.value=true;applied.value=params();}error.value='';try{const r=await get('/tracking/waybills',applied.value);if(seq!==sequence)return;rows.value=r.items.map(unpackTracking);total.value=r.total;const id=detail.value?.id||String(route.query.businessId||'');if(id)await select(id,!quiet&&!element.value?String(route.query.assetId||'')||undefined:undefined,true);else{detail.value=null;element.value=null;if(!quiet&&!themes.value&&r.items.length)await select((r.items.find((w:any)=>w.status==='IN_PROGRESS')||r.items[0]).id);}}catch(e){if(seq===sequence)error.value=message(e);}finally{activeLoads--;if(seq===sequence)busy.value=false;}}
async function search(){query.page=1;detail.value=null;element.value=null;selection++;await router.replace({query:{}});await load();}
function reset(){Object.assign(query,{waybill:'',shipper:'',cargo:'',origin:'',destination:'',asset:'',mmsi:'',min:undefined,max:undefined,status:'',page:1});search();}
async function pickAsset(a:any){if(detail.value?.id!==a.waybillId)await select(a.waybillId,a.id);else element.value=detail.value.assets.find((v:any)=>v.id===a.id);}
async function openWarning(){const w=warning.value;if(w)await select(w.waybill.id,w.taskId);}
function dismissWarning(){const w=warning.value;if(w)dismissed.value.push(w.id||w.taskId+':'+w.type);}
function closeReplay(){replay.value=false;replayAt.value=undefined;replayIds.value=[];element.value=null;}
function startReplay(){element.value=null;replay.value=true;}
function replayTime(v:any){replayAt.value=v.at;replayIds.value=v.ids;}
function switchMode(mode:string){closeReplay();query.mode=mode;query.asset='';query.mmsi='';search();}
watch(()=>detail.value?.id,()=>{if(replay.value)closeReplay();});
watch(()=>route.path,()=>{selection++;detail.value=null;element.value=null;query.page=1;load();});
onMounted(async()=>{if(route.query.taskId){try{const t=await get('/tracking/tasks/'+route.query.taskId,{includeTest:String(includeTest.value)});await router.replace({query:{businessId:t.businessId,assetId:t.id}});}catch{}}await load();const assetId=String(route.query.assetId||'');if(assetId&&detail.value)element.value=detail.value.assets.find((a:any)=>a.id===assetId);motionClock=setInterval(()=>{if(!document.hidden&&!replay.value&&mapAssets.value.some((a:any)=>a.movement))referenceAt.value=Date.now();},100);poll=setInterval(()=>{if(!document.hidden&&!busy.value&&!detailBusy.value&&!replay.value)load(true);},15000);});onBeforeUnmount(()=>{sequence++;selection++;clearInterval(poll);clearInterval(motionClock);});
</script>
<template><div class="tracking-shell"><WaybillTrackingMap ref="mapRef" :assets="mapAssets" :segments="mapSegments" :nodes="mapNodes" :selected="displayElement" :panel-open="panelOpen" :reference-at="referenceAt" :replay-at="replayAt" :replay-ids="replayIds" @select="pickAsset" @node="element=$event"><template #popup><TrackingElementPopup v-if="element&&detail&&!unlocated" :key="element.id" :element="displayElement" :waybill="detail" :include-test="includeTest" @close="element=null" @asset="pickAsset"/></template></WaybillTrackingMap><button v-if="detail&&!replay" class="start-replay" :disabled="!canReplay" @click="startReplay">轨迹回放</button><TrackingReplay v-if="replay" :assets="mapAssets" @time="replayTime" @close="closeReplay"/><div v-if="unlocated&&detail" class="unlocated-popup"><TrackingElementPopup :element="displayElement" :waybill="detail" :include-test="includeTest" @close="element=null"/></div><button v-if="!panelOpen" class="show-panel" aria-label="展开运单列表" @click="panelOpen=true"><PanelLeftOpen :size="18"/>{{themes?'专题运输':'联运运单'}}</button><aside v-if="panelOpen" class="floating-waybills" aria-label="运单查询与列表"><header class="floating-heading"><div><h1>{{themes?'专题视图':'全程跟踪'}}</h1><small>{{themes?'按运输方式查询关联运单':'联运服务运单 · 运输过程'}}</small></div><button aria-label="收起运单列表" @click="panelOpen=false"><PanelLeftClose :size="18"/></button></header><div v-if="themes" class="transport-categories" role="tablist" aria-label="专题运输分类"><button v-for="m in ['ROAD','WATER','RAIL']" :key="m" role="tab" :aria-selected="query.mode===m" :class="{active:query.mode===m}" @click="switchMode(m)"><component :is="m==='ROAD'?Truck:m==='WATER'?Ship:TrainFront" :size="16"/>{{label(m)}}</button></div><form class="floating-search" @submit.prevent="search"><div class="search-row"><el-input v-model="query.waybill" clearable placeholder="运单号 / 合同号" aria-label="查询运单号"/><el-input v-model="query.shipper" clearable placeholder="发货人" aria-label="查询发货人"/></div><template v-if="themes"><div class="search-row"><el-input v-if="query.mode!=='RAIL'" v-model="query.asset" clearable :placeholder="query.mode==='ROAD'?'车牌号':'船名'" :aria-label="query.mode==='ROAD'?'查询车牌号':'查询船名'"/><el-input v-if="query.mode==='WATER'" v-model="query.mmsi" clearable placeholder="MMSI" aria-label="查询MMSI" maxlength="9"/></div></template><template v-else-if="filtersOpen"><div class="search-row"><el-input v-model="query.cargo" clearable placeholder="货类" aria-label="查询货类"/><el-select v-model="query.status" clearable placeholder="运输进度" aria-label="查询运输进度"><el-option label="待执行" value="PENDING"/><el-option label="执行中" value="IN_PROGRESS"/><el-option label="已完成" value="COMPLETED"/></el-select></div><div class="search-row"><el-input-number v-model="query.min" :controls="false" :min="0" :precision="1" placeholder="数量下限（吨）" aria-label="查询数量下限"/><el-input-number v-model="query.max" :controls="false" :min="0" :precision="1" placeholder="数量上限（吨）" aria-label="查询数量上限"/></div><div class="search-row"><el-input v-model="query.origin" clearable placeholder="起始地" aria-label="查询起始地"/><el-input v-model="query.destination" clearable placeholder="目的地" aria-label="查询目的地"/></div></template><div class="search-actions"><button v-if="!themes" type="button" class="filter-toggle" :aria-expanded="filtersOpen" @click="filtersOpen=!filtersOpen"><SlidersHorizontal :size="14"/>筛选</button><el-button native-type="submit" type="primary" :loading="busy" size="small"><Search :size="13"/>查询</el-button><el-button size="small" @click="reset">重置</el-button></div></form><el-alert v-if="error||detailError" :title="error||detailError" type="error" :closable="false" show-icon/><div class="waybill-count"><b>{{themes?modeName+'运输':'联运运单'}}</b><span>{{total}} 个运单{{themes?' · '+viewAssets.length+' 个要素':''}}</span></div><div class="floating-list" v-loading="busy"><template v-if="!themes"><button v-for="w in rows" :key="w.id" class="waybill-card" :class="{active:detail?.id===w.id}" :aria-pressed="detail?.id===w.id" @click="select(w.id)"><header><span>{{w.waybillNo}}</span><small :class="{executing:w.status==='IN_PROGRESS'}">{{({PENDING:'待执行',IN_PROGRESS:'执行中',COMPLETED:'已完成'} as any)[w.status]}}</small></header><strong>{{w.shipper}}</strong><div class="waybill-cargo"><span>{{w.cargo}}</span><b>{{ton(w.quantityKg)}}</b></div><div class="waybill-route"><i/><span>{{w.origin}}</span><i/><span>{{w.destination}}</span></div><footer><span>{{new Set(w.assets.filter((a:any)=>a.mode==='ROAD').map((a:any)=>a.title)).size}} 辆车 · {{w.assets.filter((a:any)=>a.mode==='WATER').length}} 船次 · {{w.assets.filter((a:any)=>a.mode==='RAIL').length}} 铁路任务</span><b v-if="w.alerts.length" class="warning-count">{{w.alerts.length}} 项预警</b><small v-else>{{w.completedStages}} / {{w.stageCount}} 阶段完成</small></footer></button></template><template v-else><button v-for="a in viewAssets" :key="a.id" class="waybill-card thematic-card" :class="{active:element?.id===a.id}" :aria-pressed="element?.id===a.id" @click="pickAsset(a)"><header><span>{{a.waybill.waybillNo}}</span><small>{{label(a.status)}}</small></header><strong>{{a.title}}</strong><p v-if="a.mode==='WATER'">MMSI {{a.mmsi||'未关联'}} · 航次 {{a.voyage}}</p><p>{{a.shipper}} · {{a.grain}}<template v-if="a.mode!=='ROAD'"> · {{ton(a.quantityKg)}}</template></p><div class="thematic-route">{{a.stage.origin}} → {{a.stage.destination}}</div><footer><span>{{a.position?.dataQuality==='INITIALIZATION'?'参考位置':a.position?'已定位':a.currentNode?'节点跟踪':'等待定位'}}</span><b v-if="a.alerts.length" class="warning-count">{{a.alerts.length}} 项预警</b></footer></button></template><el-empty v-if="!busy&&(!themes&&!rows.length||themes&&!viewAssets.length)" description="暂无符合条件的运输记录" :image-size="50"/><p v-if="!busy&&detail&&!detail.assets.length" class="list-note">该运单尚未提交运输阶段，等待物流企业填写。</p></div><div class="floating-pagination"><el-pagination v-model:current-page="query.page" :total="total" :page-size="query.pageSize" small :pager-count="5" layout="prev,pager,next" @current-change="load()"/></div></aside><div v-if="warning&&!element&&!replay" class="map-warning" role="alert"><TriangleAlert :size="20"/><div><b>{{warning.waybill.referenceData?'运输参考提醒':warning.level==='HIGH'?'运输高风险':'运输提醒'}}</b><p>{{warning.message}}</p><small>{{warning.waybill.waybillNo}}</small><button @click="openWarning">查看运输详情 →</button></div><button class="warning-close" aria-label="关闭当前预警" @click="dismissWarning">×</button></div><div v-if="detailBusy" class="loading-waybill" role="status">正在加载运单过程…</div><div v-if="detail&&!replay" class="selected-waybill-summary"><b>{{detail.waybillNo}}</b><span>{{detail.cargo}} · {{ton(detail.quantityKg)}}</span><button v-for="p in detail.nodes.filter((n:any)=>n.isPort)" :key="p.id" @click="element=p"><i class="WATER"/>{{p.destination}} · 过磅确认 {{ton(p.collectedKg)}} / {{ton(p.targetKg)}}<small>已发船 {{ton(p.shippedKg)}}</small></button></div></div></template>
