t{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:6px 12px 10px}.waybill-card{display:block;width:100%;text-align:left;background:#fff;border:1px solid #e1e7ef;border-radius:8px;padding:13px;margin-bottom:10px;cursor:pointer;font-family:inherit;color:#283d55}.waybill-card.active{border-color:#e7434b;background:#fffbfb;box-shadow:inset 3px 0 #e72e38}.waybill-card:hover{border-color:#bdcbd8}.waybill-card header{display:flex;justify-content:space-between;gap:6px;color:#8a98a9;font-size:10px;margin-bottom:9px}.waybill-card header small{font-size:10px;white-space:nowrap}.waybill-card .executing{color:#278a72}.waybill-card strong{font-size:13px;line-height:1.5}.waybill-cargo{display:flex;align-items:center;gap:8px;font-size:11px;margin:9px 0}.waybill-cargo>span{padding:2px 6px;background:#f0f3f7;border-radius:4px}.waybill-cargo b{font-size:14px}.waybill-cargo em{font-style:normal;color:#a48650;font-size:9px;margin-left:auto}.waybill-route{display:grid;grid-template-columns:7px 1fr;gap:8px;font-size:11px;color:#7d8b9c}.waybill-route i{width:5px;height:5px;border:1.5px solid #459989;border-radius:50%;margin-top:4px}.waybill-route i:nth-of-type(2){border-color:#e75862}.waybill-card footer{display:flex;gap:6px;justify-content:space-between;border-top:1px solid #eef1f5;padding-top:9px;margin-top:11px;font-size:9px;color:#8a98a8;line-height:1.5}.warning-count{color:#ca6a39;font-weight:500;white-space:nowrap}.floating-pagination{display:flex;justify-content:center;padding:6px;border-top:1px solid #e9edf3}.transport-categories{display:flex;padding:12px 14px 0;gap:6px}.transport-categories button{display:flex;flex:1;justify-content:center;align-items:center;gap:7px;padding:9px 4px;border:1px solid #e5eaf0;background:#fff;color:#7d8fa2;border-radius:6px;font-size:12px;cursor:pointer}.transport-categories .active{color:#e22e38;border-color:#f2afb5;background:#fff5f5}.thematic-card p{font-size:11px;color:#8b99a9;margin:8px 0}.thematic-route{font-size:11px;line-height:1.6}.show-panel{position:absolute;top:16px;left:18px;z-index:10;display:flex;align-items:center;gap:8px;border:1px solid #e2e7ed;border-radius:7px;background:#fff;padding:12px;color:#435873;font-size:12px;cursor:pointer}.map-warning{position:absolute;right:18px;top:76px;display:flex;gap:10px;max-width:330px;background:#fff9f3;border:1px solid #edccaa;border-radius:8px;padding:14px 12px;color:#b96531;box-shadow:0 5px 16px #65442b0c;z-index:8}.map-warning>svg{flex-shrink:0}.map-warning b{font-size:12px}.map-warning p{font-size:12px;line-height:1.7;margin:6px 0}.map-warning small{display:block;color:#ae8f72;font-size:10px}.map-warning button{border:0;background:none;font-size:11px;color:#b75e2b;padding:0;margin-top:10px;cursor:pointer}.map-warning .warning-close{font-size:18px;margin:0;align-self:flex-start}.loading-waybill{position:absolute;top:72px;left:calc(50% + 130px);z-index:9;background:#fff;padding:9px 16px;border-radius:6px;font-size:12px;color:#7b8a9c}.selected-waybill-summary{position:absolute;bottom:16px;left:18px;display:flex;gap:12px;align-items:center;max-width:calc(100% - 80px);background:#fffffff5;border:1px solid #e2e8ef;padding:10px 14px;border-radius:8px;z-index:9;font-size:11px;box-shadow:0 4px 16px #2945640b;overflow-x:auto;white-space:nowrap}.selected-waybill-summary>b{font-size:11px;color:#344a64}.selected-waybill-summary>span{color:#8b99a9}.selected-waybill-summary button{border:0;border-left:1px solid #e6ebf1;background:none;padding:0 0 0 12px;color:#536b83;font-size:11px;cursor:pointer}.selected-waybill-summary button small{font-size:10px;color:#8b99a9;margin-left:4px}.selected-waybill-summary i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#2879dc;margin-right:5px}.selected-waybill-summary .WATER{background:#0b9eac}.selected-waybill-summary .RAIL{background:#7d58bd}.list-note{font-size:11px;color:#8a98a6;padding:16px;text-align:center}@media(max-width:1000px){.floating-waybills{width:316px}.map-warning{max-width:260px}}@media(max-width:760px){.floating-waybills{top:58px;width:min(316px,calc(100vw - 32px));left:14px;bottom:90px}.map-warning{top:auto;bottom:68px;right:14px;max-width:245px}.selected-waybill-summary{left:14px;right:48px;bottom:12px;max-width:none}.show-panel{top:60px;left:14px}.tracking-shell{min-height:500px}}</style>
